from __future__ import annotations

import hashlib
import json
import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Collection, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

ROLES = ("berry", "ingredient", "skill")
ANCHORS = (60, 80)
ANCHOR_WEIGHTS = {60: 0.5, 80: 0.5}
# Fixed 90th-percentile ideal-final-evolution baselines generated by the pinned
# Neroli engine (`mode=score-references`). They are independent of the box.
ABSOLUTE_REFERENCES = {
    60: {"berry": 3300.0, "ingredient": 3678.0, "skill": 5224.0},
    80: {"berry": 6884.0, "ingredient": 6065.0, "skill": 5970.0},
}
ZERO_VALUE_SUBSKILLS = {
    "Research EXP Bonus", "Sleep EXP Bonus", "Dream Shard Bonus"
}

# Base energy added by one ingredient when it is put into a dish. These values
# are also used by the pinned Neroli engine's RP ingredient component.
INGREDIENT_BASE_ENERGY = {
    "Apple": 90, "Milk": 98, "Soybean": 100, "Honey": 101,
    "Sausage": 103, "Ginger": 109, "Tomato": 110, "Egg": 115,
    "Oil": 121, "Potato": 124, "Herb": 130, "Corn": 140,
    "Cacao": 151, "Coffee": 153, "Avocado": 162, "Mushroom": 167,
    "Leek": 185, "Pumpkin": 250, "Tail": 342, "Slowpoke Tail": 342,
}


def now() -> str:
    return datetime.now(timezone.utc).isoformat()


def canonical_uid(item: Mapping[str, Any]) -> str:
    core = {
        "species": item["species"],
        "nature": item["nature"],
        "ingredients": item["ingredients"],
        "subskills": item["subskills"],
        "main_skill": item["main_skill"],
        "skill_level": item["skill_level"],
        "display_name": item.get("display_name") or "",
    }
    raw = json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode()).hexdigest()[:20]


def connect(path: Path) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(path))
    db.row_factory = sqlite3.Row
    db.executescript(Path(__file__).with_name("schema.sql").read_text())
    columns = {row["name"] for row in db.execute("PRAGMA table_info(individual)")}
    if "pokemon_type" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN pokemon_type TEXT")
    if "island_scores_json" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN island_scores_json TEXT NOT NULL DEFAULT '{}'")
    if "berry" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN berry TEXT")
    if "production_scores_json" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN production_scores_json TEXT NOT NULL DEFAULT '{}'")
    if "energy_scores_json" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN energy_scores_json TEXT NOT NULL DEFAULT '{}'")
    if "review_confirmed" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN review_confirmed INTEGER NOT NULL DEFAULT 0")
    if "archived" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN archived INTEGER NOT NULL DEFAULT 0")
    if "final_evolution" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN final_evolution TEXT")
    if "auto_verified" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN auto_verified INTEGER NOT NULL DEFAULT 0")
    if "sp_flag" not in columns:
        db.execute("ALTER TABLE individual ADD COLUMN sp_flag TEXT")
    migrate_subskill_unlocks(db)
    db.commit()
    return db


def migrate_subskill_unlocks(db: sqlite3.Connection) -> int:
    """Move stored Lv75/Lv100 subskill unlocks to the Ver.3.6.0 Lv70/Lv80."""
    from .localization import current_unlock

    changed = 0
    for row in db.execute("SELECT uid, subskills_json FROM individual "
                          "WHERE subskills_json LIKE '%75]%' OR subskills_json LIKE '%100]%'").fetchall():
        subskills = json.loads(row["subskills_json"])
        updated = [[entry[0], current_unlock(entry[1]), *entry[2:]] for entry in subskills]
        if updated != subskills:
            db.execute("UPDATE individual SET subskills_json=? WHERE uid=?",
                       (json.dumps(updated, ensure_ascii=False), row["uid"]))
            changed += 1
    return changed


def synced_sources(db: sqlite3.Connection) -> set:
    return {row["sha256"] for row in db.execute("SELECT sha256 FROM scan_source")}


def record_synced_sources(db: sqlite3.Connection,
                          sources: Iterable[Tuple[str, str, str, int]]) -> None:
    """Remember (sha256, name, reader, items) captures that were imported."""
    db.executemany(
        "INSERT OR REPLACE INTO scan_source (sha256,name,reader,items,scanned_at) VALUES (?,?,?,?,?)",
        [(*source, now()) for source in sources])
    db.commit()


def _evolves_into(stored_species: str, species: str) -> bool:
    """True when ``species`` is ``stored_species`` or one of its evolutions.

    Evolution links come from the pinned species data (``evolves_from``). When
    they are unavailable, only the same species counts as the same line.
    """
    if stored_species == species:
        return True
    from .ocr import species_metadata

    metadata = species_metadata()
    seen = {species}
    current = (metadata.get(species) or {}).get("evolves_from")
    while current and current not in seen:
        if current == stored_species:
            return True
        seen.add(current)
        current = (metadata.get(current) or {}).get("evolves_from")
    return False


def _subskill_upgrades_to(stored: str, new: str) -> bool:
    """True when subskill seeds can turn ``stored`` into ``new`` (or it is unchanged)."""
    from .engine import SUBSKILL_UPGRADES

    current, seen = stored, set()
    while current and current not in seen:
        if current == new:
            return True
        seen.add(current)
        current = SUBSKILL_UPGRADES.get(current)
    return False


def _known(value: Any) -> bool:
    return value is not None and value != ""


def is_recapture(row: Mapping[str, Any], item: Mapping[str, Any], missing: Iterable[str] = ()) -> bool:
    """Whether ``item`` can be a later capture of the stored individual ``row``.

    Level, SP, skill level, species (within one evolution line), main skill (on
    evolution) and subskills (seed upgrades) may change over time. Nature, the
    ingredient chosen in each slot and the order of subskill slots never do.
    Fields listed in ``missing`` (``ocr_missing``) are not compared; nature and
    subskills must be readable because they identify the individual.
    """
    missing = set(missing)
    if "species" in missing or "nature" in missing or "subskills" in missing:
        return False
    if row["nature"] != item.get("nature"):
        return False
    if "ingredients" not in missing:
        stored = [entry[0] for entry in json.loads(row["ingredients_json"])]
        if stored != [entry[0] for entry in item.get("ingredients", [])]:
            return False
    stored_subskills = json.loads(row["subskills_json"])
    subskills = item.get("subskills", [])
    if len(stored_subskills) != len(subskills) or not all(
            old[1] == new[1] and _subskill_upgrades_to(old[0], new[0])
            for old, new in zip(stored_subskills, subskills)):
        return False
    if not _evolves_into(row["species"], item.get("species")):
        return False
    if "main_skill" not in missing:
        if row["species"] == item.get("species") and row["main_skill"] != item.get("main_skill"):
            return False
        if _known(row["skill_level"]) and _known(item.get("skill_level")) and \
                int(item["skill_level"]) < int(row["skill_level"]):
            return False
    if "level" not in missing and _known(row["level"]) and _known(item.get("level")) and \
            int(item["level"]) < int(row["level"]):
        return False
    return True


def find_recapture(db: sqlite3.Connection, item: Mapping[str, Any], candidate_uids: Collection[str],
                   missing: Iterable[str] = ()) -> Tuple[Optional[sqlite3.Row], int]:
    """Return (row to update, number of matching rows) for a re-captured individual.

    Only rows in ``candidate_uids`` are considered. With several matches
    (identical builds), the one whose stored level and SP are not above the
    new values is chosen when it is unique, then an exact level+SP match.
    Otherwise nothing is chosen and the match count is returned so callers
    can report a possible duplicate.
    """
    missing = list(missing)
    matches = [row for row in db.execute(
                   "SELECT * FROM individual WHERE archived=0 ORDER BY uid").fetchall()
               if row["uid"] in candidate_uids and is_recapture(row, item, missing)]
    if len(matches) <= 1:
        return (matches[0] if matches else None), len(matches)

    def not_above(row: Mapping[str, Any], field: str) -> bool:
        return not (field not in missing and _known(row[field]) and _known(item.get(field))
                    and int(row[field]) > int(item[field]))

    eligible = [row for row in matches if not_above(row, "level") and not_above(row, "sp")]
    if len(eligible) == 1:
        return eligible[0], len(matches)
    exact = [row for row in eligible
             if _known(item.get("level")) and _known(item.get("sp")) and
             row["level"] == int(item["level"]) and row["sp"] == int(item["sp"])]
    if len(exact) == 1:
        return exact[0], len(matches)
    return None, len(matches)


def import_individuals(db: sqlite3.Connection, items: Iterable[Mapping[str, Any]]) -> int:
    """Insert or update individuals.

    A still capture (``capture-`` uid) or an item without uid that matches an
    individual stored before this call (see ``is_recapture``) updates that
    individual and keeps its uid. Rows inserted or matched earlier in the same
    call are never matched again, so identical-build helpers captured together
    stay distinct. When ``items`` are dicts, a merged item's ``uid`` is
    replaced by the stored uid and ``recaptured`` is set; an unresolved
    identical-build match sets ``possible_duplicates``. Dict items also get
    ``stored_uid``, the uid of the row they were written to.
    """
    from .localization import normalize_individual

    timestamp = now()
    count = 0
    candidates = {row["uid"] for row in db.execute("SELECT uid FROM individual")}
    for raw_item in items:
        item = normalize_individual(dict(raw_item))
        uid = item.get("uid")
        existing = None
        recaptured = False
        if not uid and item.get("sp") is not None:
            matches = db.execute("SELECT * FROM individual WHERE species=? AND sp=?",
                                 (item["species"], item["sp"])).fetchall()
            if len(matches) == 1:
                existing = matches[0]
                uid = existing["uid"]
        missing = set(raw_item.get("ocr_missing", []))
        if not existing and (not uid or str(uid).startswith("capture-")):
            target = uid or canonical_uid(item)
            if not db.execute("SELECT 1 FROM individual WHERE uid=?", (target,)).fetchone():
                match, match_count = find_recapture(db, item, candidates, missing)
                if match:
                    existing, uid, recaptured = match, match["uid"], True
                    if isinstance(raw_item, dict):
                        raw_item["uid"] = uid
                        raw_item["recaptured"] = True
                elif match_count > 1 and isinstance(raw_item, dict):
                    raw_item["possible_duplicates"] = match_count
        if existing:
            candidates.discard(existing["uid"])
        # A later capture may intentionally show only nature/subskills. Never
        # replace previously reviewed fields with OCR placeholders or partial
        # ingredient lists from that complementary video.
        if existing:
            if "nature" in missing:
                item["nature"] = existing["nature"]
            if "ingredients" in missing:
                item["ingredients"] = json.loads(existing["ingredients_json"])
            if "subskills" in missing:
                item["subskills"] = json.loads(existing["subskills_json"])
            if "main_skill" in missing:
                item["main_skill"] = existing["main_skill"]
                item["skill_level"] = existing["skill_level"]
        if recaptured:
            # Level and SP only go up; an unread value keeps the stored one.
            for field in ("level", "sp"):
                values = [int(v) for v in (existing[field], item.get(field))
                          if _known(v)] if field not in missing else []
                item[field] = max(values) if values else existing[field]
            if not item.get("display_name"):
                item["display_name"] = existing["display_name"]
        uid = uid or canonical_uid(item)
        if isinstance(raw_item, dict):
            raw_item["stored_uid"] = uid
        same_core = bool(existing and all((
            existing["species"] == item["species"],
            existing["nature"] == item["nature"],
            json.loads(existing["ingredients_json"]) == item["ingredients"],
            json.loads(existing["subskills_json"]) == item["subskills"],
            existing["main_skill"] == item["main_skill"],
            existing["skill_level"] == item["skill_level"],
        )))
        review_confirmed = bool(item.get("review_confirmed") or
                                (existing and existing["review_confirmed"]))
        verified = bool(review_confirmed or item.get("verified") or
                        (same_core and existing["verified"]))
        db.execute(
            """INSERT INTO individual
            (uid,species,display_name,level,nature,pokemon_type,berry,production_scores_json,energy_scores_json,island_scores_json,ingredients_json,subskills_json,
             main_skill,skill_level,sp,box_index,first_seen,last_seen,confidence,verified,review_confirmed)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(uid) DO UPDATE SET species=excluded.species,display_name=excluded.display_name,
              level=excluded.level,nature=excluded.nature,pokemon_type=excluded.pokemon_type,
              berry=excluded.berry,production_scores_json=excluded.production_scores_json,
              energy_scores_json=excluded.energy_scores_json,
              island_scores_json=excluded.island_scores_json,ingredients_json=excluded.ingredients_json,
              subskills_json=excluded.subskills_json,main_skill=excluded.main_skill,
              skill_level=excluded.skill_level,sp=excluded.sp,box_index=excluded.box_index,
              last_seen=excluded.last_seen,confidence=excluded.confidence,
              review_confirmed=MAX(individual.review_confirmed,excluded.review_confirmed),
              verified=MAX(individual.review_confirmed,excluded.verified,excluded.review_confirmed),
              auto_verified=CASE WHEN excluded.verified=1 AND excluded.review_confirmed=0
                AND individual.review_confirmed=0 THEN individual.auto_verified ELSE 0 END,
              sp_flag=NULL""",
            (uid, item["species"], item.get("display_name"), item.get("level"),
             item["nature"], item.get("pokemon_type"),
             item.get("berry"), json.dumps(item.get("production_scores", {}), ensure_ascii=False),
             json.dumps(item.get("energy_scores", {}), ensure_ascii=False),
             json.dumps(item.get("island_scores", {}), ensure_ascii=False),
             json.dumps(item["ingredients"], ensure_ascii=False),
             json.dumps(item["subskills"], ensure_ascii=False), item["main_skill"],
             item["skill_level"], item.get("sp"), item.get("box_index"),
             timestamp, timestamp, item.get("confidence", 0.0), verified, review_confirmed),
        )
        for anchor_text, scores in item.get("scores", {}).items():
            for role, score in scores.items():
                if int(anchor_text) in ANCHORS and role in ROLES:
                    db.execute(
                        """INSERT OR REPLACE INTO evaluation VALUES
                        (?,?,?,?,?,?,?,?,?)""",
                        (uid, int(anchor_text), role, float(score), None, None,
                         "imported", "imported", timestamp),
                    )
        count += 1
    db.commit()
    return count


def decide(db: sqlite3.Connection, keep_top_n: int = 2,
           protected_uids: Sequence[str] = (), low_score_threshold: float = 30.0) -> Dict[str, int]:
    people = db.execute("SELECT * FROM individual WHERE archived=0 ORDER BY species, box_index").fetchall()
    scores = {(r["uid"], r["anchor_level"], r["role"]): r["score"] for r in
              db.execute("SELECT uid,anchor_level,role,score FROM evaluation")}
    by_species: Dict[str, List[sqlite3.Row]] = {}
    for person in people:
        by_species.setdefault(person["species"], []).append(person)
    counts = {"keep": 0, "send": 0, "protected": 0}
    timestamp = now()
    for species, group in by_species.items():
        for person in group:
            uid = person["uid"]
            if uid in protected_uids:
                verdict, reason = "protected", "保護リストで指定されています"
            elif not person["verified"]:
                verdict, reason = "protected", "検証が完了していないため判定対象外です"
            elif any((uid, a, r) not in scores for a in ANCHORS for r in ROLES):
                verdict, reason = "protected", "Lv60/Lv80の全ロール評価が未完了です"
            else:
                def role_scores(candidate_uid: str) -> Dict[str, float]:
                    evaluations = {
                        anchor: {role: scores[(candidate_uid, anchor, role)] for role in ROLES}
                        for anchor in ANCHORS
                    }
                    return absolute_role_scores(evaluations)

                own_roles = role_scores(uid)
                best_role, best_role_score = max(own_roles.items(), key=lambda item: item[1])

                # A candidate is safe to send only when at least keep_top_n
                # same-species individuals are no worse at both anchors in all
                # roles, and strictly better on at least one axis. Comparing a
                # single peak score would discard useful specialists.
                dominated_by = []
                for other in group:
                    if other["uid"] == uid:
                        continue
                    other_uid = other["uid"]
                    no_worse = all(
                        scores[(other_uid, anchor, role)] >= scores[(uid, anchor, role)]
                        for anchor in ANCHORS for role in ROLES
                    )
                    strictly_better = any(
                        scores[(other_uid, anchor, role)] > scores[(uid, anchor, role)]
                        for anchor in ANCHORS for role in ROLES
                    )
                    if no_worse and strictly_better:
                        dominated_by.append(other_uid)

                if len(dominated_by) >= keep_top_n:
                    verdict = "send"
                    reason = (f"Lv60/Lv80の全ロールで同等以上、かつ一部で上回る同種個体が"
                              f"{len(dominated_by)}匹います（最高評価: {best_role}・"
                              f"{best_role_score:.1f}点）")
                else:
                    verdict = "keep"
                    reason = (f"Lv60/Lv80の全ロールでは同種上位に支配されません"
                              f"（最高評価: {best_role}・{best_role_score:.1f}点）")
            db.execute("INSERT OR REPLACE INTO decision VALUES (?,?,?,?)",
                       (uid, verdict, reason, timestamp))
            counts[verdict] += 1
    db.commit()
    return counts


def load_dashboard(db: sqlite3.Connection) -> List[Dict[str, Any]]:
    from .localization import to_japanese
    rows = db.execute("""SELECT i.*,d.verdict,d.reason FROM individual i
                         LEFT JOIN decision d ON d.uid=i.uid
                         WHERE i.archived=0 ORDER BY i.box_index""").fetchall()
    evaluations: Dict[str, Dict[int, Dict[str, float]]] = {}
    for row in db.execute("SELECT uid,anchor_level,role,score FROM evaluation"):
        evaluations.setdefault(row["uid"], {}).setdefault(row["anchor_level"], {})[row["role"]] = row["score"]
    result = []
    for row in rows:
        item_scores = evaluations.get(row["uid"], {})
        role_scores = absolute_role_scores(item_scores)
        ingredients = json.loads(row["ingredients_json"] or "[]")
        ingredient_slots = [{"name": x[0], "amount": x[1],
                             "base_energy": INGREDIENT_BASE_ENERGY.get(x[0], 0),
                             "drop_energy": x[1] * INGREDIENT_BASE_ENERGY.get(x[0], 0)}
                            for x in ingredients if len(x) >= 2]
        result.append({**dict(row), "species_ja": to_japanese("species", row["species"]),
                       "nature_ja": to_japanese("natures", row["nature"]),
                       "evaluations": item_scores,
                       "island_scores": json.loads(row["island_scores_json"] or "{}"),
                       "energy_scores": json.loads(row["energy_scores_json"] or "{}"),
                       "production_scores": json.loads(row["production_scores_json"] or "{}"),
                       "ingredient_slots": ingredient_slots,
                       "absolute_by_role": role_scores,
                       "absolute_score": max(role_scores.values(), default=0.0),
                       "review_confirmed": bool(row["review_confirmed"])})
    return result


def build_team_plans(items: Sequence[Mapping[str, Any]], team_size: int = 5) -> List[Dict[str, Any]]:
    """Select the exact best additive team for each island and training anchor.

    Island scores must come from the external game engine/input. Missing values
    are excluded instead of estimated in Python.
    """
    islands = sorted({island for item in items for island in item.get("island_scores", {})})
    plans: List[Dict[str, Any]] = []
    for island in islands:
        for mode in ("current", "60", "80"):
            candidates = []
            for item in items:
                if not item.get("verified"):
                    continue
                value = item.get("island_scores", {}).get(island, {}).get(mode)
                if value is not None:
                    candidates.append((float(value), item))
            selected = sorted(candidates, key=lambda pair: (-pair[0], pair[1]["uid"]))[:team_size]
            if selected:
                plans.append({
                    "island": island,
                    "mode": mode,
                    "total_score": round(sum(score for score, _ in selected), 2),
                    "members": [{"uid": item["uid"], "name": item.get("display_name") or item["species"],
                                 "species": item["species"], "type": item.get("pokemon_type"),
                                 "score": score} for score, item in selected],
                })
    return plans


def absolute_role_scores(evaluations: Mapping[int, Mapping[str, float]],
                         references: Mapping = ABSOLUTE_REFERENCES,
                         weights: Mapping[int, float] = ANCHOR_WEIGHTS) -> Dict[str, float]:
    """Return stable 0-100 scores based on fixed references, never box rank."""
    result: Dict[str, float] = {}
    for role in ROLES:
        if any(role not in evaluations.get(anchor, {}) for anchor in ANCHORS):
            result[role] = 0.0
            continue
        ratio = sum(weights[a] * max(0.0, evaluations[a][role]) /
                    float(references[a][role] if a in references else references[role])
                    for a in ANCHORS)
        result[role] = round(min(100.0, ratio * 100.0), 1)
    return result


# Convenience 0-100 cut points for this app's own species tier, chosen to
# roughly match a six-tier external scale (SS/S/A/B/C/D). The score itself is
# the only rigorous part; these letters are just a readable label on top of it.
TIER_CUTS = (("SS", 95.0), ("S", 85.0), ("A", 70.0), ("B", 50.0), ("C", 30.0))


def score_to_tier(score: float) -> str:
    for label, cutoff in TIER_CUTS:
        if score >= cutoff:
            return label
    return "D"


